    (* X_INTERFACE_INFO = "xilinx.com:interface:aximm_rtl:1.0 M3_AXI ARCACHE" *)
    output wire [3:0] m3_axi_arcache,
    (* X_INTERFACE_INFO = "xilinx.com:interface:aximm_rtl:1.0 M3_AXI ARPROT" *)
    output wire [2:0] m3_axi_arprot,
    (* X_INTERFACE_INFO = "xilinx.com:interface:aximm_rtl:1.0 M3_AXI ARQOS" *)
    output wire [3:0] m3_axi_arqos,
    (* X_INTERFACE_INFO = "xilinx.com:interface:aximm_rtl:1.0 M3_AXI ARID" *)
    output wire [5:0] m3_axi_arid,
    (* X_INTERFACE_INFO = "xilinx.com:interface:aximm_rtl:1.0 M3_AXI ARVALID" *)
    output wire m3_axi_arvalid,
    (* X_INTERFACE_INFO = "xilinx.com:interface:aximm_rtl:1.0 M3_AXI ARREADY" *)
    input  wire m3_axi_arready,
    (* X_INTERFACE_INFO = "xilinx.com:interface:aximm_rtl:1.0 M3_AXI RDATA" *)
    input  wire [63:0] m3_axi_rdata,
    (* X_INTERFACE_INFO = "xilinx.com:interface:aximm_rtl:1.0 M3_AXI RRESP" *)
    input  wire [1:0] m3_axi_rresp,
    (* X_INTERFACE_INFO = "xilinx.com:interface:aximm_rtl:1.0 M3_AXI RLAST" *)
    input  wire m3_axi_rlast,
    (* X_INTERFACE_INFO = "xilinx.com:interface:aximm_rtl:1.0 M3_AXI RID" *)
    input  wire [5:0] m3_axi_rid,
    (* X_INTERFACE_INFO = "xilinx.com:interface:aximm_rtl:1.0 M3_AXI RVALID" *)
    input  wire m3_axi_rvalid,
    (* X_INTERFACE_INFO = "xilinx.com:interface:aximm_rtl:1.0 M3_AXI RREADY" *)
    output wire m3_axi_rready,
    (* X_INTERFACE_INFO = "xilinx.com:interface:aximm_rtl:1.0 M3_AXI AWADDR" *)
    output wire [31:0] m3_axi_awaddr,
    (* X_INTERFACE_INFO = "xilinx.com:interface:aximm_rtl:1.0 M3_AXI AWLEN" *)
    output wire [3:0] m3_axi_awlen,
    (* X_INTERFACE_INFO = "xilinx.com:interface:aximm_rtl:1.0 M3_AXI AWSIZE" *)
    output wire [2:0] m3_axi_awsize,
    (* X_INTERFACE_INFO = "xilinx.com:interface:aximm_rtl:1.0 M3_AXI AWBURST" *)
    output wire [1:0] m3_axi_awburst,
    (* X_INTERFACE_INFO = "xilinx.com:interface:aximm_rtl:1.0 M3_AXI AWLOCK" *)
    output wire [1:0] m3_axi_awlock,
    (* X_INTERFACE_INFO = "xilinx.com:interface:aximm_rtl:1.0 M3_AXI AWCACHE" *)
    output wire [3:0] m3_axi_awcache,
    (* X_INTERFACE_INFO = "xilinx.com:interface:aximm_rtl:1.0 M3_AXI AWPROT" *)
    output wire [2:0] m3_axi_awprot,
    (* X_INTERFACE_INFO = "xilinx.com:interface:aximm_rtl:1.0 M3_AXI AWQOS" *)
    output wire [3:0] m3_axi_awqos,
    (* X_INTERFACE_INFO = "xilinx.com:interface:aximm_rtl:1.0 M3_AXI AWID" *)
    output wire [5:0] m3_axi_awid,
    (* X_INTERFACE_INFO = "xilinx.com:interface:aximm_rtl:1.0 M3_AXI AWVALID" *)
    output wire m3_axi_awvalid,
    (* X_INTERFACE_INFO = "xilinx.com:interface:aximm_rtl:1.0 M3_AXI AWREADY" *)
    input  wire m3_axi_awready,
    (* X_INTERFACE_INFO = "xilinx.com:interface:aximm_rtl:1.0 M3_AXI WDATA" *)
    output wire [63:0] m3_axi_wdata,
    (* X_INTERFACE_INFO = "xilinx.com:interface:aximm_rtl:1.0 M3_AXI WSTRB" *)
    output wire [7:0] m3_axi_wstrb,
    (* X_INTERFACE_INFO = "xilinx.com:interface:aximm_rtl:1.0 M3_AXI WLAST" *)
    output wire m3_axi_wlast,
    (* X_INTERFACE_INFO = "xilinx.com:interface:aximm_rtl:1.0 M3_AXI WID" *)
    output wire [5:0] m3_axi_wid,
    (* X_INTERFACE_INFO = "xilinx.com:interface:aximm_rtl:1.0 M3_AXI WVALID" *)
    output wire m3_axi_wvalid,
    (* X_INTERFACE_INFO = "xilinx.com:interface:aximm_rtl:1.0 M3_AXI WREADY" *)
    input  wire m3_axi_wready,
    (* X_INTERFACE_INFO = "xilinx.com:interface:aximm_rtl:1.0 M3_AXI BRESP" *)
    input  wire [1:0] m3_axi_bresp,
    (* X_INTERFACE_INFO = "xilinx.com:interface:aximm_rtl:1.0 M3_AXI BID" *)
    input  wire [5:0] m3_axi_bid,
    (* X_INTERFACE_INFO = "xilinx.com:interface:aximm_rtl:1.0 M3_AXI BVALID" *)
    input  wire m3_axi_bvalid,
    (* X_INTERFACE_INFO = "xilinx.com:interface:aximm_rtl:1.0 M3_AXI BREADY" *)
    output wire m3_axi_bready
);

    localparam NU = 4;

    // ---------------- CSRs ----------------
    reg        start;
    reg        mode;
    reg        nb2;
    reg [10:0] x_beats;
    reg [12:0] row_beats;
    reg [15:0] rows;
    reg [31:0] x_addr;
    reg [31:0] w_addr [0:NU-1];
    reg [31:0] y_addr [0:NU-1];
    reg [31:0] cycles;
    reg        counting;

    wire [NU-1:0] u_done, u_busy, u_err;
    wire [15:0] u_prog [0:NU-1];
    reg rst_n;
    always @(posedge aclk) rst_n <= aresetn;
    wire all_done = &u_done && !start;

    reg awready_r, wready_r, bvalid_r, arready_r, rvalid_r;
    reg [31:0] rdata_r;
    assign s_axi_awready = awready_r;
    assign s_axi_wready  = wready_r;
    assign s_axi_bvalid  = bvalid_r;
    assign s_axi_bresp   = 2'b00;
    assign s_axi_arready = arready_r;
    assign s_axi_rvalid  = rvalid_r;
    assign s_axi_rdata   = rdata_r;
    assign s_axi_rresp   = 2'b00;

    wire wr_go = s_axi_awvalid && s_axi_wvalid && !bvalid_r && !awready_r;
    wire rd_go = s_axi_arvalid && !rvalid_r && !arready_r;

    integer n;
    always @(posedge aclk) begin
        if (!rst_n) begin
            awready_r <= 1'b0; wready_r <= 1'b0; bvalid_r <= 1'b0;
            arready_r <= 1'b0; rvalid_r <= 1'b0; rdata_r  <= 32'd0;
            start <= 1'b0; mode <= 1'b0; nb2 <= 1'b0; x_beats <= 11'd0; row_beats <= 13'd0; rows <= 16'd0; x_addr <= 32'd0;
            cycles <= 32'd0; counting <= 1'b0;
            for (n = 0; n < NU; n = n + 1) begin
                w_addr[n] <= 32'd0;
                y_addr[n] <= 32'd0;
            end
        end else begin
            start     <= 1'b0;
            awready_r <= 1'b0;
            wready_r  <= 1'b0;
            arready_r <= 1'b0;

            if (wr_go) begin
                awready_r <= 1'b1;
                wready_r  <= 1'b1;
                bvalid_r  <= 1'b1;
                case (s_axi_awaddr[7:0])
                    8'h00: start  <= s_axi_wdata[0] && !(|u_busy);
                    8'h08: mode   <= s_axi_wdata[0];
                    8'h0C: x_beats <= s_axi_wdata[10:0];
                    8'h50: row_beats <= s_axi_wdata[12:0];
                    8'h54: nb2 <= s_axi_wdata[0];
                    8'h10: rows   <= s_axi_wdata[15:0];
                    8'h14: x_addr <= s_axi_wdata;
                    default: begin
                        for (n = 0; n < NU; n = n + 1) begin
                            if (s_axi_awaddr[7:0] == 8'h20 + 8*n) w_addr[n] <= s_axi_wdata;
                            if (s_axi_awaddr[7:0] == 8'h24 + 8*n) y_addr[n] <= s_axi_wdata;
                        end
                    end
                endcase
            end
            if (bvalid_r && s_axi_bready) bvalid_r <= 1'b0;

            if (rd_go) begin
                arready_r <= 1'b1;
                rvalid_r  <= 1'b1;
                case (s_axi_araddr[7:0])
                    8'h04: rdata_r <= {20'd0, u_err, u_done, 1'b0, |u_err, |u_busy, all_done};
                    8'h08: rdata_r <= {31'd0, mode};
                    8'h0C: rdata_r <= {21'd0, x_beats};
                    8'h50: rdata_r <= {19'd0, row_beats};
                    8'h54: rdata_r <= {31'd0, nb2};
                    8'h10: rdata_r <= {16'd0, rows};
                    8'h14: rdata_r <= x_addr;
                    8'h18: rdata_r <= cycles;
                    8'h1C: rdata_r <= 32'h47454D33;
                    default: begin
                        rdata_r <= 32'd0;
                        for (n = 0; n < NU; n = n + 1) begin
                            if (s_axi_araddr[7:0] == 8'h20 + 8*n) rdata_r <= w_addr[n];
                            if (s_axi_araddr[7:0] == 8'h24 + 8*n) rdata_r <= y_addr[n];
                            if (s_axi_araddr[7:0] == 8'h40 + 4*n) rdata_r <= {16'd0, u_prog[n]};
                        end
                    end
                endcase
            end
            if (rvalid_r && s_axi_rready) rvalid_r <= 1'b0;

            // perf counter: clocks from start until every unit is done
            if (start) begin
                cycles   <= 32'd0;
                counting <= 1'b1;
            end else if (counting) begin
                if (&u_done) counting <= 1'b0;
                else         cycles   <= cycles + 1'b1;
            end
        end
    end

    // ---------------- unit 0 ----------------
    assign m0_axi_arsize  = 3'b011;
    assign m0_axi_arburst = 2'b01;
    assign m0_axi_arlock  = 2'b00;
    assign m0_axi_arcache = 4'b0011;
    assign m0_axi_arprot  = 3'b000;
    assign m0_axi_arqos   = 4'd0;
    assign m0_axi_arid    = 6'd0;
    assign m0_axi_awsize  = 3'b011;
    assign m0_axi_awburst = 2'b01;
    assign m0_axi_awlock  = 2'b00;
    assign m0_axi_awcache = 4'b0011;
    assign m0_axi_awprot  = 3'b000;
    assign m0_axi_awqos   = 4'd0;
    assign m0_axi_awid    = 6'd0;
    assign m0_axi_wid     = 6'd0;
    assign m0_axi_wstrb   = 8'hFF;

    gemv_unit u0 (
        .clk(aclk), .rstn(aresetn),
        .start(start), .mode(mode), .nb2(nb2), .x_beats(x_beats), .row_beats(row_beats), .rows(rows),
        .x_addr(x_addr), .w_addr(w_addr[0]), .y_addr(y_addr[0]),
        .done(u_done[0]), .busy(u_busy[0]), .err(u_err[0]), .progress(u_prog[0]),
        .araddr(m0_axi_araddr), .arlen(m0_axi_arlen), .arvalid(m0_axi_arvalid), .arready(m0_axi_arready),
        .rdata(m0_axi_rdata), .rvalid(m0_axi_rvalid), .rlast(m0_axi_rlast), .rresp(m0_axi_rresp), .rready(m0_axi_rready),
        .awaddr(m0_axi_awaddr), .awlen(m0_axi_awlen), .awvalid(m0_axi_awvalid), .awready(m0_axi_awready),
        .wdata(m0_axi_wdata), .wlast(m0_axi_wlast), .wvalid(m0_axi_wvalid), .wready(m0_axi_wready),
        .bresp(m0_axi_bresp), .bvalid(m0_axi_bvalid), .bready(m0_axi_bready)
    );

    // ---------------- unit 1 ----------------
    assign m1_axi_arsize  = 3'b011;
    assign m1_axi_arburst = 2'b01;
    assign m1_axi_arlock  = 2'b00;
    assign m1_axi_arcache = 4'b0011;
    assign m1_axi_arprot  = 3'b000;
    assign m1_axi_arqos   = 4'd0;
    assign m1_axi_arid    = 6'd0;
    assign m1_axi_awsize  = 3'b011;
    assign m1_axi_awburst = 2'b01;
    assign m1_axi_awlock  = 2'b00;
    assign m1_axi_awcache = 4'b0011;
    assign m1_axi_awprot  = 3'b000;
    assign m1_axi_awqos   = 4'd0;
    assign m1_axi_awid    = 6'd0;
    assign m1_axi_wid     = 6'd0;
    assign m1_axi_wstrb   = 8'hFF;

    gemv_unit u1 (
        .clk(aclk), .rstn(aresetn),
        .start(start), .mode(mode), .nb2(nb2), .x_beats(x_beats), .row_beats(row_beats), .rows(rows),
        .x_addr(x_addr), .w_addr(w_addr[1]), .y_addr(y_addr[1]),
        .done(u_done[1]), .busy(u_busy[1]), .err(u_err[1]), .progress(u_prog[1]),
        .araddr(m1_axi_araddr), .arlen(m1_axi_arlen), .arvalid(m1_axi_arvalid), .arready(m1_axi_arready),
        .rdata(m1_axi_rdata), .rvalid(m1_axi_rvalid), .rlast(m1_axi_rlast), .rresp(m1_axi_rresp), .rready(m1_axi_rready),
        .awaddr(m1_axi_awaddr), .awlen(m1_axi_awlen), .awvalid(m1_axi_awvalid), .awready(m1_axi_awready),
        .wdata(m1_axi_wdata), .wlast(m1_axi_wlast), .wvalid(m1_axi_wvalid), .wready(m1_axi_wready),
        .bresp(m1_axi_bresp), .bvalid(m1_axi_bvalid), .bready(m1_axi_bready)
    );

    // ---------------- unit 2 ----------------
    assign m2_axi_arsize  = 3'b011;
    assign m2_axi_arburst = 2'b01;
    assign m2_axi_arlock  = 2'b00;
    assign m2_axi_arcache = 4'b0011;
    assign m2_axi_arprot  = 3'b000;
    assign m2_axi_arqos   = 4'd0;
    assign m2_axi_arid    = 6'd0;
    assign m2_axi_awsize  = 3'b011;
    assign m2_axi_awburst = 2'b01;
    assign m2_axi_awlock  = 2'b00;
    assign m2_axi_awcache = 4'b0011;
    assign m2_axi_awprot  = 3'b000;
    assign m2_axi_awqos   = 4'd0;
    assign m2_axi_awid    = 6'd0;
    assign m2_axi_wid     = 6'd0;
    assign m2_axi_wstrb   = 8'hFF;

    gemv_unit u2 (
        .clk(aclk), .rstn(aresetn),
        .start(start), .mode(mode), .nb2(nb2), .x_beats(x_beats), .row_beats(row_beats), .rows(rows),
        .x_addr(x_addr), .w_addr(w_addr[2]), .y_addr(y_addr[2]),
        .done(u_done[2]), .busy(u_busy[2]), .err(u_err[2]), .progress(u_prog[2]),
        .araddr(m2_axi_araddr), .arlen(m2_axi_arlen), .arvalid(m2_axi_arvalid), .arready(m2_axi_arready),
        .rdata(m2_axi_rdata), .rvalid(m2_axi_rvalid), .rlast(m2_axi_rlast), .rresp(m2_axi_rresp), .rready(m2_axi_rready),
        .awaddr(m2_axi_awaddr), .awlen(m2_axi_awlen), .awvalid(m2_axi_awvalid), .awready(m2_axi_awready),
        .wdata(m2_axi_wdata), .wlast(m2_axi_wlast), .wvalid(m2_axi_wvalid), .wready(m2_axi_wready),
        .bresp(m2_axi_bresp), .bvalid(m2_axi_bvalid), .bready(m2_axi_bready)
    );

    // ---------------- unit 3 ----------------
    assign m3_axi_arsize  = 3'b011;
    assign m3_axi_arburst = 2'b01;
    assign m3_axi_arlock  = 2'b00;
    assign m3_axi_arcache = 4'b0011;
    assign m3_axi_arprot  = 3'b000;
    assign m3_axi_arqos   = 4'd0;
    assign m3_axi_arid    = 6'd0;
    assign m3_axi_awsize  = 3'b011;
    assign m3_axi_awburst = 2'b01;
    assign m3_axi_awlock  = 2'b00;
    assign m3_axi_awcache = 4'b0011;
    assign m3_axi_awprot  = 3'b000;
    assign m3_axi_awqos   = 4'd0;
    assign m3_axi_awid    = 6'd0;
    assign m3_axi_wid     = 6'd0;
    assign m3_axi_wstrb   = 8'hFF;

    gemv_unit u3 (
        .clk(aclk), .rstn(aresetn),
        .start(start), .mode(mode), .nb2(nb2), .x_beats(x_beats), .row_beats(row_beats), .rows(rows),
        .x_addr(x_addr), .w_addr(w_addr[3]), .y_addr(y_addr[3]),
        .done(u_done[3]), .busy(u_busy[3]), .err(u_err[3]), .progress(u_prog[3]),
        .araddr(m3_axi_araddr), .arlen(m3_axi_arlen), .arvalid(m3_axi_arvalid), .arready(m3_axi_arready),
        .rdata(m3_axi_rdata), .rvalid(m3_axi_rvalid), .rlast(m3_axi_rlast), .rresp(m3_axi_rresp), .rready(m3_axi_rready),
        .awaddr(m3_axi_awaddr), .awlen(m3_axi_awlen), .awvalid(m3_axi_awvalid), .awready(m3_axi_awready),
        .wdata(m3_axi_wdata), .wlast(m3_axi_wlast), .wvalid(m3_axi_wvalid), .wready(m3_axi_wready),
        .bresp(m3_axi_bresp), .bvalid(m3_axi_bvalid), .bready(m3_axi_bready)
    );

endmodule
